private val DarkBg=Color(0xFF06090B);private val DarkSurface=Color(0xFF0D1418);private val DarkTeal=Color(0xFF48D7C5);private val DarkText=Color(0xFFF5F8F8);private val DarkMuted=Color(0xFF8B9A9F)
